const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const core=TalentCore,client=TalentClient;
const revisions=new Map(),writeRevisions=new Map();let saving=0,teamUsers=[];
let library=[],activeId='',state,selected=null,view='workspace',busy=false,parsing=false,submitting=false,tasks=[],lastDeleted=null,polling=false,ready=false,saveChain=Promise.resolve();
const uid=()=>crypto.randomUUID();
const blank=()=>({id:uid(),title:'未命名岗位',jd:'',skills:[],people:[],tracked:[],accounts:'',job:null});
function message(text){$('#message').textContent=text}
async function api(path,body){return client.request(path,body)}
function localSave(){try{sessionStorage.setItem('talentlens-client-'+client.user.id,JSON.stringify({drafts:library.map(j=>({id:j.id,accounts:j.accounts,jd:j.jd})),activeId}))}catch{message('浏览器草稿保存失败；已提交结果仍保存在工作空间。')}}
function remember(jobs){for(const j of jobs){revisions.set(j.id,j.revision);if(!saving)writeRevisions.set(j.id,j.revision)}}
function save(){state.accounts=$('#accounts').value;state.title=$('#job-title').value.trim()||state.job?.title||'未命名岗位';localSave();const snapshot=[structuredClone(state)];saving++;saveChain=saveChain.catch(()=>{}).then(async()=>{for(const j of snapshot)if(writeRevisions.has(j.id))j.revision=writeRevisions.get(j.id);const result=await api('/api/workspace',{jobs:snapshot});const saved=result.jobs.filter(j=>snapshot.some(x=>x.id===j.id));remember(saved);for(const j of saved)writeRevisions.set(j.id,j.revision);for(const j of library){const server=saved.find(x=>x.id===j.id);if(server){j.revision=server.revision;j.ownerId=server.ownerId}}return result}).catch(async e=>{if(e.status===409){const latest=await api('/api/workspace');library=latest.jobs;remember(library);selectJob(library.some(j=>j.id===activeId)?activeId:library[0]?.id)}message('保存失败：'+e.message);throw e}).finally(()=>saving--);saveChain.catch(()=>{});return saveChain}
const job=()=>({...state.job,jd:state.job?.jd||state.jd,criteria:state.skills});
const profile=p=>core.profile(p,job());
function lock(){const active=tasks.some(t=>['pending','running'].includes(t.status));busy=parsing||submitting||active;['#parse','#evaluate','#new-job','#job-select','#job-title','#addskill','#jd','#custom','#import','#clear'].forEach(id=>$(id).disabled=busy||!ready);$('#rubric').querySelectorAll('input,textarea,button').forEach(el=>el.disabled=busy);$('#list').querySelectorAll('[data-delete]').forEach(el=>el.disabled=busy);$('#detail').querySelectorAll('#track,#update-person').forEach(el=>el.disabled=busy)}
function accountLinks(){const input=$('#accounts'),key=core.key(job());$('#account-highlight').innerHTML=input.value.split(/([\s,，;；]+)/).map(token=>{if(!token||/^[\s,，;；]+$/.test(token))return esc(token);const login=usernames(token)[0],p=state.people.find(p=>p.login.toLowerCase()===login);return p&&core.normalize(p.criteriaKey)===key?`<span class="evaluated">${esc(token)}</span>`:esc(token)}).join('')+'\n';$('#account-highlight').scrollTop=input.scrollTop;$('#account-highlight').scrollLeft=input.scrollLeft}
function usernames(input){return [...new Set(input.split(/[\s,，;；]+/).filter(Boolean).map(v=>{if(/^https?:/i.test(v)){try{const u=new URL(v);return u.hostname==='github.com'&&u.pathname.split('/').filter(Boolean).length===1?u.pathname.split('/').filter(Boolean)[0]:''}catch{return ''}}return v.replace(/^@/,'')}).map(v=>v.toLowerCase()))]}
function skillUI(){const skills=state.skills;$('#skill-summary').innerHTML=skills.slice(0,5).map(s=>`<span>${esc(s.name)}</span>`).join('')+(skills.length>5?`<span class="more-skills">＋${skills.length-5} 项</span>`:'');$('#criteria-count').textContent='· '+skills.length+' 项';$('#criteria-panel').hidden=!skills.length;
 $('#rubric').innerHTML=skills.map((s,i)=>`<details><summary>${esc(s.name)} · 权重 ${s.weight} · ${s.observable?'公开可验证':'需沟通'}</summary><div class="criterion-form"><label>重要程度 <input data-index="${i}" data-field="weight" type="number" min="1" max="5" value="${s.weight}"></label><label>技能名称<input data-index="${i}" data-field="name" value="${esc(s.name)}"></label><label>要求<textarea data-index="${i}" data-field="requirement">${esc(s.requirement)}</textarea></label><label><input type="checkbox" data-index="${i}" data-field="observable" ${s.observable?'checked':''}> 能从公开 GitHub 资料验证</label><label>原文依据${s.id.startsWith('custom-')?'（自定义标准可留空）':''}<textarea data-index="${i}" data-field="sourceQuote">${esc(s.sourceQuote)}</textarea></label>${['zero','partial','strong'].map((key,k)=>`<label>${['零分依据','部分证据','充分证据'][k]}<textarea data-index="${i}" data-field="rubric.${key}">${esc(s.rubric?.[key])}</textarea></label>`).join('')}<label>沟通验证问题<textarea data-index="${i}" data-field="verificationQuestion">${esc(s.verificationQuestion)}</textarea></label><button class="secondary" data-remove="${i}">删除标准</button></div></details>`).join('')}
function visiblePeople(){const q=$('#search').value.trim().toLowerCase(),type=$('#type-filter').value;return state.people.filter(p=>(view!=='tracked'||state.tracked.includes(p.login))&&(type==='all'||(p.accountType||'User')===type)&&[p.login,p.name,...profile(p).skills.filter(s=>s.value!==null).map(s=>s.name)].join(' ').toLowerCase().includes(q)).sort((a,b)=>{if(type==='all'&&a.accountType!==b.accountType)return (a.accountType==='Organization'?1:0)-(b.accountType==='Organization'?1:0);if($('#sort').value==='name')return a.login.localeCompare(b.login);const pa=profile(a),pb=profile(b);return (pb.valid?pb.score??-1:-2)-(pa.valid?pa.score??-1:-2)||pb.coverage-pa.coverage})}
function render(){if(!state)return;$('#admin-owner-controls').hidden=client.user.role!=='admin'||!state.revision;if(teamUsers.length)$('#job-owner').value=state.ownerId||client.user.id;$('#job-select').innerHTML=library.map(j=>`<option value="${esc(j.id)}" ${j.id===activeId?'selected':''}>${esc(j.title)} · ${j.people.length} 个账号</option>`).join('');$('#count').textContent=state.tracked.length;$('#mode').textContent='个人与组织分别排序';skillUI();accountLinks();batchUI();const people=visiblePeople();$('#resultcount').textContent=people.length;
 $('#list').innerHTML=people.length?people.map(p=>{const f=profile(p);return `<div class="candidate ${selected===p.login?'selected':''}" role="button" tabindex="0" aria-expanded="${selected===p.login}" aria-controls="detail" data-person="${esc(p.login)}"><span class="avatar">${esc(p.login.slice(0,2).toUpperCase())}</span><div class="info"><strong>${esc(p.name||p.login)}</strong><p>@${esc(p.login)} · ${p.accountType==='Organization'?'组织':'个人'} · ${p.repos.length} 个仓库</p><p>${esc(f.skills.filter(s=>s.value!==null).slice(0,4).map(s=>s.name).join(' · ')||'暂无可验证技能')}</p><p class="${f.fresh?'':'status-label'}">${esc(p.time||'历史结果')} · ${f.fresh?'7 天内更新':p.capturedAt?'已过期 / 待更新':'历史采集时间未记录'}</p><p class="review-badge">${f.valid&&p.review?.status==='verified'&&core.normalize(p.review.criteriaKey)===core.normalize(p.criteriaKey)?'已人工复核':p.review?.status==='needs_info'?'待补充资料':'待人工复核'}</p></div><div class="score">${!f.valid?'需重新评估':f.score===null?'待验证':f.score+'%'}<small>${p.accountType==='Organization'?'组织项目相关度':'有证据技能匹配'}<br>证据覆盖 ${f.valid?f.coverage:0}% · 待验证 ${f.pending}</small></div><span class="muted">↗</span><button class="candidate-delete" data-delete="${esc(p.login)}" aria-label="删除 ${esc(p.name||p.login)} 的评估结果">删除</button></div>`}).join(''):'<div class="empty">暂无符合条件的账号<br><span class="muted">解析岗位后添加账号，或调整筛选。</span></div>';detail();lock()}
function detail(){const p=state.people.find(p=>p.login===selected);$('#detail').hidden=!p;$('.result-layout').classList.toggle('details-open',!!p);if(!p){$('#detail').innerHTML='';return}const f=profile(p),known=f.skills.filter(s=>s.value!==null),strengths=known.filter(s=>s.value>=.7),gaps=known.filter(s=>s.value<.5),pending=f.skills.filter(s=>s.value===null);
 $('#detail').innerHTML=`<button id="collapse-detail" class="secondary collapse-detail">收起 ×</button><p class="eyebrow">匹配细节</p><div class="detail-head"><span class="avatar">${esc(p.login.slice(0,2).toUpperCase())}</span><div><h2>${esc(p.name||p.login)}</h2><a href="https://github.com/${encodeURIComponent(p.login)}" target="_blank" rel="noopener">@${esc(p.login)} ↗</a></div><button class="secondary" id="track">${state.tracked.includes(p.login)?'✓ 已追踪':'＋ 追踪'}</button></div><div class="metric-row"><div><strong>${f.valid&&f.score!==null?f.score+'%':'待验证'}</strong><small>有证据技能匹配</small></div><div><strong>${f.valid?f.coverage:0}%</strong><small>证据覆盖</small></div><div><strong>${f.pending}</strong><small>待验证项</small></div></div><div class="summary-box">优势：${esc(strengths.map(s=>s.name).join('、')||'暂未发现充分证据')}<br>已发现缺口：${esc(gaps.map(s=>s.name).join('、')||'暂未发现明确缺口')}<br>待沟通：${esc(pending.map(s=>s.name).join('、')||'个人职责和贡献深度')}</div><p class="muted">${esc(p.time)} · ${esc(p.model||'历史模型')} · ${f.fresh?'近期结果':p.capturedAt?'超过 7 天':'历史采集时间未记录'} <button id="update-person" class="secondary task-button">更新评估</button></p>${p.accountType==='Organization'?'<p class="muted">组织项目相关性不能视为个人能力。</p>':''}${!f.valid?'<p class="muted">标准已变更，需要重新评估。</p>':''}<details><summary>查看分析摘要与采集范围</summary><p>${esc(p.assessment.summary)}</p><p>${esc((p.warnings||[]).join('；'))}</p><p>读取 ${p.sampledRepos??p.repos.length} 个仓库摘要，最多 8 份 README；贡献记录仅作为职责线索。</p>${(p.selection||[]).map(r=>`<p><a href="${esc(githubLink(r.url))}" target="_blank" rel="noopener">${esc(r.name)} ↗</a> · ${esc(r.reason)}</p>`).join('')}</details>${reviewHTML(p)}${f.skills.map(s=>`<details class="evidence"><summary>${esc(s.name)} · ${s.value===null?'待验证':Math.round(s.value*100)+'分'} ${s.assessment?'· '+({low:'低置信',medium:'中置信',high:'高置信'}[s.assessment.confidence]||''):''}</summary><p>${esc(s.assessment?.reason||'未发现可用证据')}</p><p>沟通问题：${esc(s.assessment?.verificationQuestion||s.verificationQuestion)}</p>${s.e.map(e=>`<a href="${esc(e.repo.html_url)}" target="_blank" rel="noopener">${esc(e.repo.name)} ↗ · ${esc(e.kind)}</a>`).join('')}</details>`).join('')}`;
 $('#review-save').onclick=async()=>{try{const result=await api('/api/reviews',{jobId:activeId,revision:state.revision,login:p.login,status:$('#review-status').value,note:$('#review-note').value});const index=library.findIndex(j=>j.id===activeId);library[index]=result.job;state=result.job;remember([result.job]);render();message('人工复核已保存，模型评分保持原样。')}catch(e){message(e.message)}};$('#collapse-detail').onclick=()=>{selected=null;render()};$('#track').onclick=()=>{state.tracked=state.tracked.includes(p.login)?state.tracked.filter(n=>n!==p.login):[...state.tracked,p.login];save();render()};$('#update-person').onclick=()=>startBatch([p.login],true)}
function batchUI(){const visible=tasks.filter(t=>t.jobId===activeId&&['pending','running','failed'].includes(t.status));$('#batch-status').innerHTML=visible.length?'<div class="batch-head">评估进度'+(visible.some(t=>['pending','running'].includes(t.status))?'<button id="cancel-batch" class="secondary">取消未完成任务</button>':'')+'</div>'+visible.slice(-10).map(t=>`<div class="batch-row ${t.status}"><strong>@${esc(t.login)}</strong><span>${esc(t.message)}</span>${t.status==='failed'?`<button class="secondary task-button" data-retry="${esc(t.login)}">重试</button>`:''}</div>`).join(''):''}
async function syncTasks(){if(polling||saving||parsing||submitting)return;polling=true;try{const data=await api('/api/workspace');const wasActive=tasks.some(t=>['pending','running'].includes(t.status));const tasksChanged=JSON.stringify(tasks)!==JSON.stringify(data.tasks);tasks=data.tasks||[];const changed=data.jobs.length!==library.length||data.jobs.some(j=>revisions.get(j.id)!==j.revision);if(changed){if(document.activeElement?.closest('#rubric,.review-box')&&!busy){message('岗位有新更新；结束编辑后将同步。');return}const drafts=library;library=data.jobs;for(const j of library){const draft=drafts.find(x=>x.id===j.id);if(draft)j.accounts=draft.accounts}remember(library);if(!library.some(j=>j.id===activeId)){if(!library.length)library=[blank()];selectJob(library[0].id)}else{state=library.find(j=>j.id===activeId);$('#job-title').value=state.title;$('#jd').value=state.jd;localSave();render()}}else if(tasksChanged)render();lock();if(wasActive&&!tasks.some(t=>['pending','running'].includes(t.status)))message('评估完成并保存，请展开结果进行人工复核。');$('#usage-status').textContent=`今日模型调用 ${data.usage.calls}/${data.usage.dailyCalls} · Token ${data.usage.tokens.toLocaleString()}/${data.usage.dailyTokens.toLocaleString()}`}catch(e){message('连接中断，将自动重连：'+e.message)}finally{polling=false}}
async function startBatch(only=null,force=false){if(busy||!ready)return;if(!state.job||!state.skills.length)return message('请先解析 JD 并生成标准');if(state.job.jd!==$('#jd').value.trim())return message('JD 已修改，请重新解析');const names=only||usernames($('#accounts').value);if(!names.length||names.some(n=>! /^[a-z0-9](?:[a-z0-9-]{0,37}[a-z0-9])?$/.test(n)))return message('请输入有效的 GitHub 用户名或主页链接');const pending=names.filter(n=>force||!state.people.some(p=>p.login.toLowerCase()===n&&profile(p).valid));if(!pending.length)return message('输入账号均已评估，已自动跳过；需要刷新时请在详情中更新');if(!$('#llm-consent').checked)return message('请先确认将 JD 与公开资料发送至模型服务。');try{submitting=true;lock();await save();const result=await api('/api/tasks',{jobId:activeId,logins:pending.slice(0,10),force,consentVersion:client.consentVersion});tasks=result.tasks;message(`已加入后台队列 ${result.tasks.length} 个账号。${pending.length>10?'剩余 '+(pending.length-10)+' 个请在本批结束后继续。':''}刷新页面可恢复进度。`);render();syncTasks()}catch(e){message(e.message)}finally{submitting=false;lock()}}
$('#evaluate').onclick=()=>startBatch();$('#batch-status').onclick=async e=>{if(e.target.dataset.retry)return startBatch([e.target.dataset.retry],!!tasks.filter(t=>t.jobId===activeId&&t.login===e.target.dataset.retry).at(-1)?.force);if(e.target.id==='cancel-batch'){for(const t of tasks.filter(t=>['pending','running'].includes(t.status)))await api('/api/tasks/cancel',{id:t.id});await syncTasks()}};
$('#parse').onclick=async()=>{if(busy)return;if(!$('#llm-consent').checked)return message('请先确认将 JD 与公开资料发送至模型服务。');const jd=$('#jd').value.trim();if(!jd)return message('请先输入岗位 JD');parsing=true;lock();message('正在生成评估标准…');try{const result=await api('/api/parse',{jd,consentVersion:client.consentVersion});state.jd=jd;state.job=result;state.skills=result.criteria;if(state.title==='未命名岗位'){$('#job-title').value=result.title;state.title=result.title}await save();message(`已生成 ${state.skills.length} 项标准，权重可直接调整。`);render()}catch(e){message(e.message)}finally{parsing=false;lock()}};
$('#rubric').onchange=e=>{const {index,field}=e.target.dataset;if(index===undefined||!field||busy)return;const c=state.skills[Number(index)];let value=field==='weight'?Math.max(1,Math.min(5,Number(e.target.value)||1)):field==='observable'?e.target.checked:e.target.value;if(field.startsWith('rubric.'))c.rubric[field.split('.')[1]]=value;else c[field]=value;save();message(field==='weight'?'已按新权重重算，无需重新调用模型。':'评估标准已更新，已有结果需重新评估。');accountLinks();$('#criteria-count').textContent='· '+state.skills.length+' 项';const people=visiblePeople();$('#resultcount').textContent=people.length;renderKeepingEditor()};
function renderKeepingEditor(){const open=[...$('#rubric').querySelectorAll('details')].map(d=>d.open);render();$('#rubric').querySelectorAll('details').forEach((d,i)=>d.open=open[i])}
$('#rubric').onclick=e=>{if(e.target.dataset.remove!==undefined&&!busy){state.skills.splice(Number(e.target.dataset.remove),1);save();render()}};
$('#addskill').onclick=()=>{const name=$('#custom').value.trim().slice(0,50);if(!state.job)return message('请先解析岗位');if(!name||state.skills.some(c=>c.name.toLowerCase()===name.toLowerCase()))return message('请输入不重复的技能名称');state.skills.push({id:'custom-'+uid(),name,weight:3,requirement:name,sourceQuote:'',observable:true,rubric:{zero:'有明确不满足要求的证据',partial:'有相关项目线索，贡献深度待确认',strong:'有充分相关项目及个人贡献证据'},verificationQuestion:'请介绍 '+name+' 的个人职责与成果'});$('#custom').value='';save();render();const last=$('#rubric').querySelectorAll('details');last[last.length-1].open=true};
$('#custom').onkeydown=e=>{if(e.key==='Enter')$('#addskill').click()};
$('#accounts').oninput=()=>{state.accounts=$('#accounts').value;localSave();accountLinks()};$('#accounts').onscroll=accountLinks;$('#accounts').onchange=()=>{if(!busy)save()};
$('#jd').oninput=()=>{state.jd=$('#jd').value;localSave()};$('#jd').onchange=()=>{if(!busy)save()};$('#job-title').onchange=()=>{save();render()};
function selectJob(id){if(!id){library=[blank()];id=library[0].id}state=library.find(j=>j.id===id);activeId=id;selected=null;lastDeleted=null;$('#jd').value=state.jd;$('#accounts').value=state.accounts||'';$('#job-title').value=state.title;localSave();render()}
$('#job-select').onchange=async e=>{try{await save();selectJob(e.target.value)}catch{}};$('#new-job').onclick=async()=>{await save();const fresh=blank();library.push(fresh);selectJob(fresh.id);save();message('已创建新岗位；原岗位和人才结果已保留。')};
$('#list').onclick=e=>{const remove=e.target.closest('[data-delete]');if(remove){if(busy)return;const login=remove.dataset.delete,person=state.people.find(p=>p.login===login);lastDeleted={person,tracked:state.tracked.includes(login),jobId:activeId};state.people=state.people.filter(p=>p.login!==login);state.tracked=state.tracked.filter(n=>n!==login);if(selected===login)selected=null;save();render();$('#message').innerHTML=`已删除 @${esc(login)}。 <button class="undo-delete" data-undo="true">撤销</button>`;return}const row=e.target.closest('[data-person]');if(row){selected=selected===row.dataset.person?null:row.dataset.person;render()}};
$('#list').onkeydown=e=>{if(!e.target.closest('[data-delete]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.closest('[data-person]')?.click()}};
$('#message').onclick=e=>{if(e.target.dataset.undo&&lastDeleted&&lastDeleted.jobId===activeId){state.people.push(lastDeleted.person);if(lastDeleted.tracked)state.tracked.push(lastDeleted.person.login);lastDeleted=null;save();render();message('已恢复结果')}};
$('#search').oninput=render;$('#sort').onchange=render;$('#type-filter').onchange=()=>{selected=null;render()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));selected=null;render()});$('#method').onclick=()=>$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();
function githubLink(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='github.com'?u.href:'#'}catch{return '#'}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export').onclick=()=>{const people=visiblePeople();if(!people.length)return message('当前筛选没有结果');const rows=[['岗位','账号','类型','匹配度','证据覆盖率','待验证项数','优势','待验证技能','采集时间','人工复核','复核备注'],...people.map(p=>{const f=profile(p);return [state.title,p.login,p.accountType==='Organization'?'组织':'个人',f.valid?f.score??'待验证':'标准已变更',f.valid?f.coverage:0,f.pending,f.skills.filter(s=>s.value>=.7).map(s=>s.name).join(';'),f.skills.filter(s=>s.value===null).map(s=>s.name).join(';'),p.capturedAt||p.time,p.review?.status||'pending',p.review?.note||'']})];download('talentlens-filtered.csv','\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')};
$('#backup').onclick=()=>download('talentlens-backup.json',JSON.stringify({version:4,jobs:library,exportedAt:new Date().toISOString()},null,2),'application/json');
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('备份超过 20 MB');const data=JSON.parse(await file.text());if(![3,4].includes(data.version)||!Array.isArray(data.jobs))throw Error('请选择 TalentLens 完整备份');const incoming=data.jobs.map(j=>({...j,id:uid(),revision:undefined,ownerId:undefined,title:j.title+'（导入）'})),merged=[...library,...incoming];const result=await api('/api/workspace',{jobs:merged});library=result.jobs;remember(library);selectJob(incoming[0]?.id||activeId);message(`已导入 ${incoming.length} 个岗位，原数据已保留`)}catch(e){message('导入失败：'+e.message)}finally{e.target.value=''}};
$('#clear').onclick=()=>{if(busy)return;const original=structuredClone(state);state.people=[];state.tracked=[];state.accounts='';$('#accounts').value='';lastDeleted=null;save();render();message('已清空当前岗位的人才结果；其他岗位保留。')};
function reviewHTML(p){const review=p.review,status=review?.status||'pending';return `<div class="review-box"><h3>人工复核</h3><p class="muted">核对证据、补充沟通结论。复核状态不替代模型评分，也不自动作出录用决定。</p><label>状态<select id="review-status"><option value="pending" ${status==='pending'?'selected':''}>待复核</option><option value="verified" ${status==='verified'?'selected':''}>已核对公开证据</option><option value="needs_info" ${status==='needs_info'?'selected':''}>需补充资料</option></select></label><label>复核备注<textarea id="review-note" maxlength="5000" placeholder="记录已确认的个人职责、补充资料及待沟通事项">${esc(review?.note||'')}</textarea></label><button id="review-save" class="secondary">保存复核</button>${review?`<p class="muted">${esc(review.reviewer)} · ${esc(new Date(review.at).toLocaleString())}</p>`:''}</div>`}
async function loadOwners(){if(client.user.role!=='admin')return;const data=await api('/api/admin/users');teamUsers=data.users;$('#job-owner').innerHTML=teamUsers.filter(u=>u.enabled).map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('');if(state)$('#job-owner').value=state.ownerId||client.user.id}
window.addEventListener('talentlens-team-loaded',loadOwners);
$('#assign-job').onclick=async()=>{if(busy)return message('请等待评估完成后分配岗位。');try{await save();const result=await api('/api/admin/assign',{jobId:activeId,ownerId:$('#job-owner').value,revision:state.revision});library=result.jobs;remember(library);selectJob(activeId);message('岗位负责人已更新。')}catch(e){message(e.message)}};
async function init(){try{await client.ready;let local;try{local=JSON.parse(sessionStorage.getItem('talentlens-client-'+client.user.id))}catch{}const data=await api('/api/workspace');library=data.jobs;remember(library);if(library.length&&client.user.role==='admin'){localStorage.removeItem('talentlens-v3');localStorage.removeItem('talentlens-v2')}if(!library.length)library=[blank()];for(const j of library){const draft=local?.drafts?.find(x=>x.id===j.id);if(draft){j.accounts=draft.accounts||'';j.jd=draft.jd}}activeId=library.some(j=>j.id===local?.activeId)?local.activeId:library[0].id;tasks=data.tasks||[];ready=true;selectJob(activeId);if(!data.jobs.length)await save();const config=await api('/api/config');$('.status').textContent='● '+config.provider+' · '+config.model;client.consentVersion=config.consentVersion;$('#llm-consent').checked=sessionStorage.getItem('talentlens-consent-'+client.user.id)===config.consentVersion;$('#llm-consent').onchange=()=>{if($('#llm-consent').checked)sessionStorage.setItem('talentlens-consent-'+client.user.id,config.consentVersion);else sessionStorage.removeItem('talentlens-consent-'+client.user.id)};if(!config.configured)message('请联系管理员配置模型 API 密钥');await client.refreshUsage();await loadOwners();setInterval(syncTasks,2000)}catch(e){message('无法加载工作空间：'+e.message);ready=false}}
init();
